import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisState } from "../types";

export const getAIInsights = async (analysis: AnalysisState) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const summary = {
    totalStudents: analysis.students.length,
    classes: analysis.classes,
    subjects: analysis.subjects,
    schoolAverage: analysis.schoolStats.average,
    subjectAverages: analysis.schoolStats.subjectStats
  };

  const prompt = `
    Based on the following student performance data summary, provide 4 critical insights for educators:
    Data Summary: ${JSON.stringify(summary)}

    The insights should cover:
    1. Overall academic health of the school.
    2. Specific subjects that need attention (weakest performance).
    3. High-performing areas to be maintained.
    4. Actionable pedagogical recommendations.

    Return the insights in a structured JSON format.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              content: { type: Type.STRING },
              type: { type: Type.STRING }
            },
            required: ["title", "content", "type"]
          }
        }
      }
    });

    return JSON.parse(response.text.trim() || "[]");
  } catch (error) {
    console.error("AI Insights Error:", error);
    return [];
  }
};

/**
 * 为 NotebookLM 生成结构化报告并生成 PPT 幻灯片大纲
 */
export const generatePresentationOutline = async (analysis: AnalysisState, periodName: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const context = {
    period: periodName,
    summary: {
      total: analysis.students.length,
      avg: analysis.schoolStats.average,
      best: analysis.schoolStats.max,
      subjects: analysis.subjects,
    }
  };

  const prompt = `
    Create a professional academic presentation outline for a school board based on the following exam data for "${periodName}".
    The presentation should be designed for NotebookLM processing and direct PPT generation.

    Data Context: ${JSON.stringify(context)}

    Generate a JSON object with a list of "slides". Each slide should have:
    - title: Heading of the slide.
    - points: 3-4 bullet points of detailed analysis or observation.
    - speakerNotes: Suggested speech script for the presenter.
    - layout: Suggest a layout (TITLE, CONTENT, or COMPARISON).

    Focus on data-driven trends and professional academic language.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            slides: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  points: { type: Type.ARRAY, items: { type: Type.STRING } },
                  speakerNotes: { type: Type.STRING },
                  layout: { type: Type.STRING }
                },
                required: ["title", "points", "speakerNotes"]
              }
            }
          },
          required: ["slides"]
        }
      }
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("PPT Outline Generation Error:", error);
    throw error;
  }
};

