import { useTranslation } from '../context/LanguageContext';
import { generatePresentationOutline } from '../services/geminiService';

declare var PptxGenJS: any;

interface ReportCenterModalProps {
  isOpen: boolean;
  onClose: () => void;
  data: AnalysisState;
  selectedPeriod: string;
}

const ReportCenterModal: React.FC<ReportCenterModalProps> = ({ isOpen, onClose, data, selectedPeriod }) => {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(false);
  const [outline, setOutline] = useState<any>(null);
  const [status, setStatus] = useState<'idle' | 'generating' | 'completed' | 'error'>('idle');

  const generateReport = async () => {
    setLoading(true);
    setStatus('generating');
    try {
      const result = await generatePresentationOutline(data, selectedPeriod);
      setOutline(result);
      setStatus('completed');
    } catch (err) {
      console.error(err);
      setStatus('error');
    } finally {
      setLoading(false);
    }
  };

  const downloadPPT = () => {
    if (!outline) return;

    const pptx = new PptxGenJS();
    pptx.layout = 'LAYOUT_16x9';

    // Title Slide
    let slide = pptx.addSlide();
    slide.background = { fill: '2563EB' }; // Blue-600
    slide.addText(`Academic Performance Report`, { x: 0.5, y: 1.5, w: '90%', fontSize: 44, color: 'FFFFFF', bold: true, align: 'center' });
    slide.addText(`Period: ${selectedPeriod}`, { x: 0.5, y: 2.5, w: '90%', fontSize: 24, color: 'FFFFFF', align: 'center' });
    slide.addText(`Generated by EduAnalytics AI`, { x: 0.5, y: 4.5, w: '90%', fontSize: 14, color: 'FFFFFF', align: 'center' });

    // Content Slides from AI Outline
    outline.slides.forEach((s: any) => {
      let contentSlide = pptx.addSlide();
      contentSlide.addText(s.title, { x: 0.5, y: 0.5, w: '90%', fontSize: 32, color: '1E293B', bold: true, border: { type: 'none', pt: 1, color: 'E2E8F0' } });

      const bullets = s.points.map((p: string) => ({ text: p, options: { bullet: true, color: '475569', fontSize: 18, margin: 5 } }));
      contentSlide.addText(bullets, { x: 0.8, y: 1.5, w: '80%', h: 3 });

      // Add Speaker Notes
      contentSlide.addNotes(s.speakerNotes);
    });

    pptx.writeFile({ fileName: `EduAnalytics_Report_${selectedPeriod}.pptx` });
  };

  const copyForNotebookLM = () => {
    if (!outline) return;
    const text = outline.slides.map((s: any) => {
      return `## ${s.title}\n\n${s.points.map((p: string) => `- ${p}`).join('\n')}\n\n*Presenter Notes: ${s.speakerNotes}*`;
    }).join('\n\n---\n\n');

    navigator.clipboard.writeText(text);
    alert('Structure copied to clipboard! You can paste this into a new document for NotebookLM.');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-4xl rounded-3xl shadow-2xl overflow-hidden border border-gray-100 flex flex-col max-h-[90vh]">
        <div className="px-8 py-6 border-b border-gray-50 flex items-center justify-between bg-gray-50/50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-600 rounded-xl">
              <Sparkles className="w-6 h-6 text-white" />
            </div>
            <div>
              <h2 className="text-xl font-black text-gray-900">AI Report Center</h2>
              <p className="text-xs text-gray-500">Transform raw data into professional presentations</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
            <X className="w-6 h-6 text-gray-400" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
          {status === 'idle' && (
            <div className="flex flex-col items-center justify-center py-20 text-center space-y-6">
              <div className="w-24 h-24 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center animate-bounce">
                <Presentation className="w-12 h-12" />
              </div>
              <div className="space-y-2">
                <h3 className="text-lg font-bold text-gray-800">Ready to Analyze</h3>
                <p className="text-gray-500 max-w-md mx-auto">
                  Our AI will synthesize all data from <span className="font-bold text-blue-600">{selectedPeriod}</span> into a multi-slide presentation structure suitable for stakeholders and NotebookLM.
                </p>
              </div>
              <button 
                onClick={generateReport}
                className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-black shadow-xl shadow-blue-200 hover:scale-105 active:scale-95 transition-all flex items-center gap-2"
              >
                <Sparkles className="w-5 h-5" /> Start AI Generation
              </button>
            </div>
          )}

          {status === 'generating' && (
            <div className="flex flex-col items-center justify-center py-20 space-y-6">
              <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
              <div className="text-center">
                <p className="text-gray-900 font-black">AI is composing your report...</p>
                <p className="text-xs text-gray-400 mt-1 italic">Reasoning through subject averages and ranking shifts</p>
              </div>
            </div>
          )}

          {status === 'completed' && outline && (
            <div className="space-y-8 animate-in slide-in-from-bottom-4">
              <div className="bg-emerald-50 border border-emerald-100 p-6 rounded-2xl flex items-center gap-4">
                <CheckCircle2 className="w-10 h-10 text-emerald-500" />
                <div>
                  <h4 className="font-bold text-emerald-900">Presentation Ready!</h4>
                  <p className="text-xs text-emerald-700">Generated {outline.slides.length} comprehensive slides with data insights.</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100 space-y-4">
                  <div className="flex items-center gap-2 text-blue-600 mb-2">
                    <Presentation className="w-5 h-5" />
                    <span className="text-[10px] font-black uppercase tracking-widest">PowerPoint Export</span>
                  </div>
                  <p className="text-sm text-gray-600 leading-relaxed">
                    Download a standard .pptx file with high-quality layouts and speaker notes. Ready for your next board meeting.
                  </p>
                  <button 
                    onClick={downloadPPT}
                    className="w-full py-3 bg-white border-2 border-blue-100 text-blue-600 rounded-xl font-bold hover:bg-blue-50 transition-all flex items-center justify-center gap-2"
                  >
                    <Download className="w-4 h-4" /> Download PPTX
                  </button>
                </div>

                <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100 space-y-4">
                  <div className="flex items-center gap-2 text-indigo-600 mb-2">
                    <FileText className="w-5 h-5" />
                    <span className="text-[10px] font-black uppercase tracking-widest">NotebookLM Integration</span>
                  </div>
                  <p className="text-sm text-gray-600 leading-relaxed">
                    Copy the structured data to your clipboard. Paste it into NotebookLM to deep-dive into trends and ask custom questions.
                  </p>
                  <button 
                    onClick={copyForNotebookLM}
                    className="w-full py-3 bg-white border-2 border-indigo-100 text-indigo-600 rounded-xl font-bold hover:bg-indigo-50 transition-all flex items-center justify-center gap-2"
                  >
                    <Copy className="w-4 h-4" /> Copy for NotebookLM
                  </button>
                </div>
              </div>

              <div className="space-y-4 pt-4">
                <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest">Slide Preview</h4>
                <div className="grid grid-cols-1 gap-4">
                  {outline.slides.map((s: any, idx: number) => (
                    <div key={idx} className="bg-white border border-gray-100 rounded-2xl p-5 shadow-sm group hover:border-blue-200 transition-all">
                      <div className="flex items-center justify-between mb-3">
                        <span className="text-[10px] font-black text-blue-500 uppercase">Slide {idx + 1}: {s.layout}</span>
                      </div>
                      <h5 className="font-bold text-gray-800 text-sm mb-2">{s.title}</h5>
                      <ul className="space-y-1">
                        {s.points.map((p: string, pIdx: number) => (
                          <li key={pIdx} className="text-xs text-gray-500 flex items-start gap-2">
                            <div className="w-1.5 h-1.5 rounded-full bg-blue-200 mt-1.5" />
                            {p}
                          </li>
                        ))}
                      </ul>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {status === 'error' && (
            <div className="flex flex-col items-center justify-center py-20 text-center space-y-4">
              <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center">
                <X className="w-8 h-8" />
              </div>
              <p className="font-bold text-gray-900">Failed to generate report</p>
              <button onClick={generateReport} className="text-blue-600 hover:underline">Retry Generation</button>
            </div>
          )}
