        <div className="px-8 py-6 border-t border-gray-50 bg-gray-50/50 flex justify-between items-center">
          <div className="flex items-center gap-4 text-[10px] text-gray-400 font-bold uppercase tracking-widest">
            <div className="flex items-center gap-1"><Layout className="w-3 h-3" /> 16:9 Aspect</div>
            <div className="flex items-center gap-1"><Sparkles className="w-3 h-3" /> AI Optimized</div>
          </div>
          <button 
            onClick={onClose}
            className="px-6 py-2 bg-gray-900 text-white rounded-xl text-xs font-bold hover:bg-gray-800 transition-all"
          >
            Close Center
          </button>
        </div>
      </div>
    </div>
  );
};

